/* Reset & Base */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --clr-bg: #f9f9f7;
  --clr-surface: #ffffff;
  --clr-primary: #1a1a1a;
  --clr-accent: #d4471e;
  --clr-accent-light: #fdf0ec;
  --clr-muted: #6b6b6b;
  --clr-border: #e5e5e0;
  --clr-deal-bg: #0f1623;
  --clr-deal-text: #ffffff;
  --radius: 12px;
  --radius-sm: 6px;
  --shadow: 0 2px 12px rgba(0,0,0,.07);
  --shadow-hover: 0 6px 24px rgba(0,0,0,.13);
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --transition: 0.2s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--clr-bg);
  color: var(--clr-primary);
  line-height: 1.6;
  font-size: 16px;
}

a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
button { cursor: pointer; font-family: inherit; }
ul { list-style: none; }

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--clr-primary);
  color: #fff;
  padding: .5rem 1rem;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  z-index: 1000;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ── Header ─────────────────────────────── */
.site-header {
  background: var(--clr-surface);
  border-bottom: 1px solid var(--clr-border);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
  display: flex;
  align-items: center;
  gap: 2rem;
  height: 68px;
}

.site-logo {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -.04em;
  flex-shrink: 0;
  color: var(--clr-primary);
}
.site-logo span { color: var(--clr-accent); }

.site-nav { flex: 1; }
.site-nav ul {
  display: flex;
  gap: .25rem;
}
.site-nav a {
  padding: .4rem .75rem;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  font-weight: 500;
  color: var(--clr-muted);
  transition: color var(--transition), background var(--transition);
}
.site-nav a:hover,
.site-nav a[aria-current="page"] {
  color: var(--clr-primary);
  background: var(--clr-bg);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: .75rem;
  flex-shrink: 0;
}

.search-form {
  display: flex;
  align-items: center;
  background: var(--clr-bg);
  border: 1px solid var(--clr-border);
  border-radius: 99px;
  padding: .35rem .35rem .35rem .9rem;
  gap: .5rem;
}
.search-form input {
  border: none;
  background: transparent;
  font-family: inherit;
  font-size: .875rem;
  width: 180px;
  outline: none;
  color: var(--clr-primary);
}
.search-form input::placeholder { color: var(--clr-muted); }
.search-form button {
  background: var(--clr-primary);
  color: #fff;
  border: none;
  border-radius: 99px;
  padding: .35rem .7rem;
  display: flex;
  align-items: center;
  justify-content: center;
}
.search-form button svg { width: 16px; height: 16px; }

.icon-btn {
  background: none;
  border: none;
  padding: .45rem;
  border-radius: var(--radius-sm);
  color: var(--clr-primary);
  transition: background var(--transition);
  display: flex;
  align-items: center;
  position: relative;
}
.icon-btn:hover { background: var(--clr-bg); }
.icon-btn svg { width: 22px; height: 22px; }

.cart-badge {
  position: absolute;
  top: -2px;
  right: -2px;
  background: var(--clr-accent);
  color: #fff;
  font-size: .625rem;
  font-weight: 700;
  border-radius: 99px;
  min-width: 16px;
  height: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 3px;
}

/* ── Announcement Bar ─────────────────── */
.announcement-bar {
  background: var(--clr-primary);
  color: #fff;
  text-align: center;
  padding: .55rem 1rem;
  font-size: .8125rem;
  font-weight: 500;
  letter-spacing: .02em;
}
.announcement-bar a { color: #fff; text-decoration: underline; text-underline-offset: 2px; }

/* ── Layout Helpers ───────────────────── */
.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section { padding: 4rem 0; }
.section--tight { padding: 2.5rem 0; }

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 2rem;
  gap: 1rem;
}
.section-title {
  font-size: clamp(1.375rem, 2.5vw, 1.75rem);
  font-weight: 800;
  letter-spacing: -.03em;
}
.section-subtitle {
  color: var(--clr-muted);
  font-size: .9rem;
  margin-top: .25rem;
}
.view-all {
  font-size: .875rem;
  font-weight: 600;
  color: var(--clr-accent);
  white-space: nowrap;
  flex-shrink: 0;
  padding: .4rem .9rem;
  border: 1.5px solid var(--clr-accent);
  border-radius: 99px;
  transition: background var(--transition), color var(--transition);
}
.view-all:hover { background: var(--clr-accent); color: #fff; }

/* ── Hero ─────────────────────────────── */
.hero {
  background: var(--clr-primary);
  color: #fff;
  overflow: hidden;
  position: relative;
  min-height: 520px;
  display: flex;
  align-items: center;
}
.hero::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 70% 50%, rgba(212,71,30,.25) 0%, transparent 65%);
  pointer-events: none;
}
.hero-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 4rem 1.5rem;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
  position: relative;
  z-index: 1;
  width: 100%;
}
.hero-eyebrow {
  display: inline-block;
  background: rgba(212,71,30,.2);
  color: #f07050;
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  padding: .35rem .8rem;
  border-radius: 99px;
  margin-bottom: 1.25rem;
}
.hero-title {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 900;
  letter-spacing: -.04em;
  line-height: 1.05;
  margin-bottom: 1.25rem;
}
.hero-title em {
  font-style: normal;
  color: #f07050;
}
.hero-desc {
  color: rgba(255,255,255,.72);
  font-size: 1.05rem;
  max-width: 420px;
  margin-bottom: 2rem;
}
.hero-actions { display: flex; gap: .75rem; flex-wrap: wrap; }

.btn {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .75rem 1.5rem;
  border-radius: 99px;
  font-size: .9375rem;
  font-weight: 700;
  border: 2px solid transparent;
  transition: all var(--transition);
  line-height: 1;
}
.btn--primary { background: var(--clr-accent); color: #fff; }
.btn--primary:hover { background: #b83b18; }
.btn--outline {
  background: transparent;
  border-color: rgba(255,255,255,.35);
  color: #fff;
}
.btn--outline:hover { border-color: #fff; background: rgba(255,255,255,.08); }

.hero-image-wrap {
  position: relative;
  aspect-ratio: 1 / 1;
  max-width: 480px;
  justify-self: end;
}
.hero-image-wrap::before {
  content: '';
  position: absolute;
  inset: -20px;
  background: radial-gradient(circle, rgba(212,71,30,.18) 0%, transparent 70%);
  border-radius: 50%;
}
.hero-img-placeholder {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: linear-gradient(135deg, #2a2a3a 0%, #1a1a2a 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 6rem;
  position: relative;
  z-index: 1;
  overflow: hidden;
}
.hero-img-placeholder::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 60%, rgba(0,0,0,.3) 100%);
}

/* ── Category Pills ────────────────────── */
.category-strip { padding: 2rem 0; border-bottom: 1px solid var(--clr-border); }
.category-list {
  display: flex;
  gap: .75rem;
  overflow-x: auto;
  padding-bottom: .25rem;
  scrollbar-width: none;
}
.category-list::-webkit-scrollbar { display: none; }
.category-pill {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .5rem;
  padding: 1rem 1.25rem;
  background: var(--clr-surface);
  border: 1.5px solid var(--clr-border);
  border-radius: var(--radius);
  white-space: nowrap;
  flex-shrink: 0;
  transition: all var(--transition);
  font-size: .8125rem;
  font-weight: 600;
  color: var(--clr-muted);
  min-width: 90px;
}
.category-pill .cat-icon { font-size: 1.5rem; }
.category-pill:hover,
.category-pill[aria-selected="true"] {
  border-color: var(--clr-primary);
  color: var(--clr-primary);
  background: var(--clr-bg);
}

/* ── Product Cards ─────────────────────── */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.25rem;
}

.product-card {
  background: var(--clr-surface);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
  transition: box-shadow var(--transition), transform var(--transition);
  display: flex;
  flex-direction: column;
  position: relative;
}
.product-card:hover { box-shadow: var(--shadow-hover); transform: translateY(-2px); }

.product-badge {
  position: absolute;
  top: .75rem;
  left: .75rem;
  background: var(--clr-accent);
  color: #fff;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: .25rem .6rem;
  border-radius: 99px;
  z-index: 2;
}
.product-badge--new { background: #1a6b47; }
.product-badge--hot { background: #c8371c; }

.product-wishlist {
  position: absolute;
  top: .75rem;
  right: .75rem;
  background: rgba(255,255,255,.9);
  border: none;
  border-radius: 50%;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  color: var(--clr-muted);
  transition: all var(--transition);
  backdrop-filter: blur(4px);
}
.product-wishlist:hover,
.product-wishlist[aria-pressed="true"] { color: var(--clr-accent); background: #fff; }
.product-wishlist svg { width: 16px; height: 16px; }

.product-img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  background: var(--clr-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3.5rem;
}

.product-body { padding: 1rem; flex: 1; display: flex; flex-direction: column; gap: .4rem; }
.product-brand { font-size: .75rem; font-weight: 600; color: var(--clr-muted); text-transform: uppercase; letter-spacing: .06em; }
.product-name { font-size: .9375rem; font-weight: 700; line-height: 1.35; }
.product-rating {
  display: flex;
  align-items: center;
  gap: .35rem;
  font-size: .8125rem;
  color: var(--clr-muted);
}
.stars { color: #f5a623; letter-spacing: -.05em; }
.product-footer {
  padding: .75rem 1rem 1rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .5rem;
}
.product-price {
  display: flex;
  align-items: baseline;
  gap: .4rem;
}
.price-current { font-size: 1.125rem; font-weight: 800; }
.price-original { font-size: .875rem; color: var(--clr-muted); text-decoration: line-through; }
.price-discount { font-size: .75rem; font-weight: 700; color: #1a6b47; background: #e8f5f0; padding: .15rem .4rem; border-radius: 4px; }

.add-to-cart {
  background: var(--clr-primary);
  color: #fff;
  border: none;
  border-radius: 99px;
  padding: .45rem .9rem;
  font-size: .8125rem;
  font-weight: 700;
  white-space: nowrap;
  transition: background var(--transition);
  display: flex;
  align-items: center;
  gap: .35rem;
}
.add-to-cart:hover { background: #333; }
.add-to-cart svg { width: 14px; height: 14px; }

/* ── Deals Section ─────────────────────── */
.deals-section {
  background: var(--clr-deal-bg);
  color: var(--clr-deal-text);
  padding: 4rem 0;
}
.deals-section .section-title { color: #fff; }
.deals-section .view-all { color: #f07050; border-color: #f07050; }
.deals-section .view-all:hover { background: #f07050; color: #fff; }

.deals-grid {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 1.25rem;
}

.deal-hero-card {
  background: linear-gradient(135deg, #1e2c45 0%, #0f1623 100%);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: var(--radius);
  padding: 2rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  position: relative;
  overflow: hidden;
  min-height: 380px;
}
.deal-hero-card::before {
  content: '';
  position: absolute;
  bottom: -40px;
  right: -40px;
  width: 200px;
  height: 200px;
  background: radial-gradient(circle, rgba(212,71,30,.2) 0%, transparent 70%);
  pointer-events: none;
}
.deal-label {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  background: rgba(212,71,30,.15);
  color: #f07050;
  border: 1px solid rgba(212,71,30,.3);
  border-radius: 99px;
  padding: .3rem .75rem;
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  margin-bottom: 1rem;
  width: fit-content;
}
.deal-title { font-size: 1.5rem; font-weight: 800; margin-bottom: .5rem; }
.deal-desc { color: rgba(255,255,255,.6); font-size: .9rem; margin-bottom: 1.5rem; }
.deal-price { font-size: 2rem; font-weight: 900; color: #f07050; margin-bottom: 1.5rem; }
.deal-price small { font-size: 1rem; font-weight: 400; color: rgba(255,255,255,.5); text-decoration: line-through; margin-left: .5rem; }

.countdown {
  display: flex;
  gap: .5rem;
  margin-bottom: 1.5rem;
}
.countdown-unit {
  background: rgba(255,255,255,.07);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: var(--radius-sm);
  padding: .5rem .6rem;
  text-align: center;
  min-width: 52px;
}
.countdown-num {
  font-size: 1.25rem;
  font-weight: 800;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.countdown-label { font-size: .625rem; color: rgba(255,255,255,.5); text-transform: uppercase; letter-spacing: .08em; margin-top: .2rem; }

.deal-cta {
  background: var(--clr-accent);
  color: #fff;
  border: none;
  border-radius: 99px;
  padding: .75rem 1.5rem;
  font-size: .9rem;
  font-weight: 700;
  width: 100%;
  transition: background var(--transition);
}
.deal-cta:hover { background: #b83b18; }

.deals-secondary {
  display: grid;
  grid-template-rows: 1fr 1fr;
  gap: 1.25rem;
}

.deal-card {
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: var(--radius);
  padding: 1.5rem;
  display: flex;
  gap: 1.25rem;
  align-items: center;
  transition: background var(--transition);
}
.deal-card:hover { background: rgba(255,255,255,.07); }

.deal-img {
  width: 100px;
  height: 100px;
  border-radius: var(--radius-sm);
  background: rgba(255,255,255,.06);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  flex-shrink: 0;
}
.deal-info { flex: 1; }
.deal-brand { font-size: .75rem; color: rgba(255,255,255,.4); text-transform: uppercase; letter-spacing: .08em; font-weight: 600; margin-bottom: .25rem; }
.deal-name { font-size: 1rem; font-weight: 700; margin-bottom: .35rem; }
.deal-rating { font-size: .8125rem; color: rgba(255,255,255,.5); margin-bottom: .75rem; }
.deal-prices { display: flex; align-items: center; gap: .6rem; flex-wrap: wrap; }
.deal-current { font-size: 1.25rem; font-weight: 800; color: #f07050; }
.deal-original { font-size: .875rem; color: rgba(255,255,255,.35); text-decoration: line-through; }
.deal-pct { background: rgba(212,71,30,.2); color: #f07050; border: 1px solid rgba(212,71,30,.3); font-size: .75rem; font-weight: 700; padding: .2rem .5rem; border-radius: 4px; }

.deal-add {
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.15);
  color: #fff;
  border-radius: 99px;
  padding: .5rem 1rem;
  font-size: .8125rem;
  font-weight: 700;
  white-space: nowrap;
  flex-shrink: 0;
  transition: background var(--transition);
}
.deal-add:hover { background: var(--clr-accent); border-color: var(--clr-accent); }

/* ── Promo Banners ─────────────────────── */
.promo-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.25rem;
}
.promo-card {
  border-radius: var(--radius);
  overflow: hidden;
  position: relative;
  min-height: 200px;
  display: flex;
  align-items: flex-end;
  padding: 1.5rem;
  background: var(--clr-primary);
  transition: transform var(--transition);
}
.promo-card:hover { transform: translateY(-3px); }
.promo-card:nth-child(1) { background: linear-gradient(135deg, #1a3a5c, #0d2035); }
.promo-card:nth-child(2) { background: linear-gradient(135deg, #2d1a1a, #1a0d0d); }
.promo-card:nth-child(3) { background: linear-gradient(135deg, #1a2d1a, #0d1a0d); }
.promo-bg-emoji {
  position: absolute;
  top: 1rem;
  right: 1rem;
  font-size: 3.5rem;
  opacity: .25;
  line-height: 1;
}
.promo-content { position: relative; z-index: 1; }
.promo-tag { font-size: .7rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; opacity: .6; color: #fff; margin-bottom: .35rem; }
.promo-title { font-size: 1.2rem; font-weight: 800; color: #fff; line-height: 1.2; margin-bottom: .75rem; }
.promo-link {
  display: inline-flex;
  align-items: center;
  gap: .3rem;
  color: #fff;
  font-size: .8125rem;
  font-weight: 700;
  opacity: .8;
  transition: opacity var(--transition);
}
.promo-link:hover { opacity: 1; }
.promo-link svg { width: 14px; height: 14px; }

/* ── Editorial / Blog ──────────────────── */
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 1.25rem;
}
.editorial-card {
  background: var(--clr-surface);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
  transition: box-shadow var(--transition), transform var(--transition);
  display: flex;
  flex-direction: column;
}
.editorial-card:hover { box-shadow: var(--shadow-hover); transform: translateY(-2px); }
.editorial-card--featured {
  grid-column: span 2;
  display: grid;
  grid-template-columns: 1fr 1fr;
}
.editorial-img {
  aspect-ratio: 16/9;
  background: var(--clr-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  overflow: hidden;
}
.editorial-card--featured .editorial-img {
  aspect-ratio: auto;
  min-height: 280px;
}
.editorial-img img { width: 100%; height: 100%; object-fit: cover; }
.editorial-body { padding: 1.5rem; flex: 1; display: flex; flex-direction: column; }
.editorial-meta {
  display: flex;
  align-items: center;
  gap: .75rem;
  font-size: .75rem;
  color: var(--clr-muted);
  margin-bottom: .75rem;
}
.editorial-tag {
  background: var(--clr-accent-light);
  color: var(--clr-accent);
  padding: .2rem .6rem;
  border-radius: 99px;
  font-weight: 700;
  font-size: .7rem;
}
.editorial-title {
  font-size: 1.0625rem;
  font-weight: 800;
  letter-spacing: -.02em;
  line-height: 1.35;
  margin-bottom: .5rem;
}
.editorial-card--featured .editorial-title { font-size: 1.375rem; }
.editorial-excerpt { font-size: .875rem; color: var(--clr-muted); line-height: 1.6; flex: 1; margin-bottom: 1rem; }
.editorial-readmore {
  font-size: .8125rem;
  font-weight: 700;
  color: var(--clr-accent);
  display: inline-flex;
  align-items: center;
  gap: .3rem;
  transition: gap var(--transition);
}
.editorial-readmore:hover { gap: .55rem; }
.editorial-readmore svg { width: 14px; height: 14px; }

/* ── Perks Bar ─────────────────────────── */
.perks-bar {
  background: var(--clr-surface);
  border-top: 1px solid var(--clr-border);
  border-bottom: 1px solid var(--clr-border);
  padding: 2rem 0;
}
.perks-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
}
.perk {
  display: flex;
  align-items: center;
  gap: .9rem;
}
.perk-icon {
  width: 44px;
  height: 44px;
  background: var(--clr-bg);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
}
.perk-title { font-size: .875rem; font-weight: 700; }
.perk-desc { font-size: .8125rem; color: var(--clr-muted); }

/* ── Newsletter ─────────────────────────── */
.newsletter-section {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
  padding: 4rem 0;
  text-align: center;
  color: #fff;
}
.newsletter-section h2 {
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 900;
  letter-spacing: -.04em;
  margin-bottom: .5rem;
}
.newsletter-section p { color: rgba(255,255,255,.6); margin-bottom: 2rem; font-size: .9375rem; }
.newsletter-form {
  display: flex;
  max-width: 440px;
  margin: 0 auto;
  gap: .5rem;
  background: rgba(255,255,255,.07);
  border: 1px solid rgba(255,255,255,.15);
  border-radius: 99px;
  padding: .35rem .35rem .35rem 1.25rem;
}
.newsletter-form input {
  flex: 1;
  background: transparent;
  border: none;
  font-family: inherit;
  font-size: .9375rem;
  color: #fff;
  outline: none;
  min-width: 0;
}
.newsletter-form input::placeholder { color: rgba(255,255,255,.4); }
.newsletter-form button {
  background: var(--clr-accent);
  color: #fff;
  border: none;
  border-radius: 99px;
  padding: .65rem 1.25rem;
  font-size: .875rem;
  font-weight: 700;
  white-space: nowrap;
  transition: background var(--transition);
}
.newsletter-form button:hover { background: #b83b18; }
.newsletter-note { margin-top: 1rem; font-size: .8125rem; color: rgba(255,255,255,.4); }

/* ── Footer ─────────────────────────────── */
.site-footer {
  background: var(--clr-primary);
  color: rgba(255,255,255,.75);
  padding: 3.5rem 0 2rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 2.5rem;
  margin-bottom: 2.5rem;
}
.footer-brand p {
  font-size: .875rem;
  color: rgba(255,255,255,.5);
  margin-top: .75rem;
  max-width: 260px;
  line-height: 1.65;
}
.footer-social { display: flex; gap: .5rem; margin-top: 1.25rem; }
.social-link {
  width: 34px;
  height: 34px;
  background: rgba(255,255,255,.08);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,.6);
  font-size: .875rem;
  font-weight: 700;
  transition: all var(--transition);
}
.social-link:hover { background: var(--clr-accent); color: #fff; }
.footer-col h3 { font-size: .9375rem; font-weight: 700; color: #fff; margin-bottom: 1rem; }
.footer-col ul { display: flex; flex-direction: column; gap: .5rem; }
.footer-col a {
  font-size: .875rem;
  color: rgba(255,255,255,.5);
  transition: color var(--transition);
}
.footer-col a:hover { color: #fff; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.08);
  padding-top: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  font-size: .8125rem;
  color: rgba(255,255,255,.35);
  flex-wrap: wrap;
}
.footer-legal { display: flex; gap: 1.25rem; }
.footer-legal a { color: rgba(255,255,255,.35); transition: color var(--transition); }
.footer-legal a:hover { color: rgba(255,255,255,.75); }

/* ── Cart Drawer ─────────────────────────── */
.cart-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.5);
  z-index: 200;
  backdrop-filter: blur(2px);
}
.cart-overlay.open { display: block; }
.cart-drawer {
  position: fixed;
  top: 0;
  right: -100%;
  width: min(400px, 100vw);
  height: 100%;
  background: var(--clr-surface);
  z-index: 201;
  display: flex;
  flex-direction: column;
  transition: right .3s ease;
  box-shadow: -4px 0 32px rgba(0,0,0,.15);
}
.cart-drawer.open { right: 0; }
.cart-header {
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--clr-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.cart-header h2 { font-size: 1.125rem; font-weight: 800; }
.close-cart {
  background: var(--clr-bg);
  border: none;
  border-radius: 8px;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--clr-primary);
  font-size: 1.1rem;
  transition: background var(--transition);
}
.close-cart:hover { background: var(--clr-border); }
.cart-items { flex: 1; overflow-y: auto; padding: 1rem 1.5rem; }
.cart-empty { text-align: center; padding: 3rem 0; color: var(--clr-muted); font-size: .9375rem; }
.cart-item {
  display: flex;
  gap: .75rem;
  padding: .75rem 0;
  border-bottom: 1px solid var(--clr-border);
}
.cart-item-img {
  width: 60px;
  height: 60px;
  border-radius: 8px;
  background: var(--clr-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  flex-shrink: 0;
}
.cart-item-info { flex: 1; }
.cart-item-name { font-size: .875rem; font-weight: 700; }
.cart-item-price { font-size: .8125rem; color: var(--clr-muted); margin-top: .2rem; }
.cart-item-qty {
  display: flex;
  align-items: center;
  gap: .5rem;
  margin-top: .5rem;
}
.qty-btn {
  background: var(--clr-bg);
  border: 1px solid var(--clr-border);
  border-radius: 4px;
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: .875rem;
  font-weight: 700;
  transition: background var(--transition);
}
.qty-btn:hover { background: var(--clr-border); }
.qty-num { font-size: .875rem; font-weight: 600; min-width: 1.5rem; text-align: center; }
.cart-footer {
  padding: 1.25rem 1.5rem;
  border-top: 1px solid var(--clr-border);
}
.cart-subtotal {
  display: flex;
  justify-content: space-between;
  font-size: .9375rem;
  margin-bottom: 1rem;
}
.cart-subtotal span:last-child { font-weight: 800; }
.checkout-btn {
  display: block;
  width: 100%;
  background: var(--clr-primary);
  color: #fff;
  border: none;
  border-radius: 99px;
  padding: .9rem;
  font-size: .9375rem;
  font-weight: 700;
  text-align: center;
  transition: background var(--transition);
}
.checkout-btn:hover { background: #333; }

/* ── Toast ─────────────────────────────── */
.toast-container {
  position: fixed;
  bottom: 1.5rem;
  left: 50%;
  transform: translateX(-50%);
  z-index: 300;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .5rem;
  pointer-events: none;
}
.toast {
  background: var(--clr-primary);
  color: #fff;
  padding: .7rem 1.25rem;
  border-radius: 99px;
  font-size: .875rem;
  font-weight: 600;
  box-shadow: 0 4px 16px rgba(0,0,0,.2);
  opacity: 0;
  transform: translateY(12px);
  transition: opacity .25s ease, transform .25s ease;
  pointer-events: auto;
}
.toast.show { opacity: 1; transform: translateY(0); }

/* ── Responsive ─────────────────────────── */
@media (max-width: 1024px) {
  .deals-grid { grid-template-columns: 1fr; }
  .deals-secondary { grid-template-rows: auto; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .hero-inner { grid-template-columns: 1fr; }
  .hero-image-wrap { display: none; }
  .site-nav { display: none; }
  .search-form input { width: 130px; }
  .promo-grid { grid-template-columns: 1fr; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card--featured { grid-column: auto; grid-template-columns: 1fr; }
  .editorial-card--featured .editorial-img { min-height: 200px; }
  .perks-grid { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; text-align: center; }
}

@media (max-width: 480px) {
  .header-inner { gap: 1rem; }
  .search-form { display: none; }
  .perks-grid { grid-template-columns: 1fr; }
  .deal-card { flex-direction: column; align-items: flex-start; }
  .deal-add { align-self: flex-start; }
}

/* Focus visible styles for accessibility */
:focus-visible {
  outline: 2px solid var(--clr-accent);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

