    { id: 1, brand: 'AeroTech', name: 'Pro Runner X1 Sneakers', price: 119, original: 159, rating: 4.8, reviews: 2341, icon: '👟', badge: 'sale', badgeClass: '' },
    { id: 2, brand: 'LuxeWear', name: 'Merino Wool Crewneck', price: 89, original: null, rating: 4.6, reviews: 871, icon: '🧥', badge: 'new', badgeClass: 'product-badge--new' },
    { id: 3, brand: 'TechGear', name: 'Wireless Noise-Cancelling Headphones', price: 199, original: 279, rating: 4.9, reviews: 5102, icon: '🎧', badge: 'hot', badgeClass: 'product-badge--hot' },
    { id: 4, brand: 'HomeHaven', name: 'Ceramic Pour-Over Coffee Set', price: 54, original: null, rating: 4.7, reviews: 639, icon: '☕', badge: 'new', badgeClass: 'product-badge--new' },
    { id: 5, brand: 'ActiveEdge', name: 'Yoga Mat Ultra-Grip 6mm', price: 42, original: 65, rating: 4.5, reviews: 1203, icon: '🧘', badge: 'sale', badgeClass: '' },
    { id: 6, brand: 'UrbanKit', name: 'Leather Minimalist Wallet', price: 34, original: null, rating: 4.6, reviews: 428, icon: '👛', badge: null, badgeClass: '' },
    { id: 7, brand: 'BrightHome', name: 'Smart LED Desk Lamp', price: 67, original: 89, rating: 4.8, reviews: 1876, icon: '💡', badge: 'sale', badgeClass: '' },
    { id: 8, brand: 'FreshBrews', name: 'Insulated Tumbler 24oz', price: 29, original: null, rating: 4.7, reviews: 3214, icon: '🥤', badge: null, badgeClass: '' },
  ];

  const CART = new Map();

  /* ── Render products ───────────────────────── */
  function discountPct(price, original) {
    return original ? Math.round((1 - price / original) * 100) : 0;
  }

  function renderStars(rating) {
    const full = Math.floor(rating);
    const half = rating % 1 >= 0.5;
    return '★'.repeat(full) + (half ? '½' : '') + '☆'.repeat(5 - full - (half ? 1 : 0));
  }

  function buildProductCard(p) {
    const pct = discountPct(p.price, p.original);
    return `
      <article class="product-card" data-product-id="${p.id}">
        ${p.badge ? `<span class="product-badge ${p.badgeClass}" aria-label="${p.badge} item">${p.badge}</span>` : ''}
        <button class="product-wishlist" aria-pressed="false" aria-label="Add ${p.name} to wishlist">
          <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/>
          </svg>
        </button>
        <div class="product-img" role="img" aria-label="${p.name} product image">${p.icon}</div>
        <div class="product-body">
          <p class="product-brand">${p.brand}</p>
          <h3 class="product-name">${p.name}</h3>
          <div class="product-rating">
            <span class="stars" aria-hidden="true">${renderStars(p.rating)}</span>
            <span>${p.rating} <span class="visually-hidden">out of 5</span></span>
            <span>(${p.reviews.toLocaleString()})</span>
          </div>
        </div>
        <div class="product-footer">
          <div class="product-price">
            <span class="price-current">$${p.price}</span>
            ${p.original ? `<span class="price-original" aria-label="Original price $${p.original}">$${p.original}</span>` : ''}
            ${pct ? `<span class="price-discount" aria-label="${pct} percent off">${pct}% off</span>` : ''}
          </div>
          <button class="add-to-cart" aria-label="Add ${p.name} to cart">
            <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
              <path d="M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z"/><line x1="3" y1="6" x2="21" y2="6"/>
              <path d="M16 10a4 4 0 0 1-8 0"/>
            </svg>
            Add
          </button>
        </div>
      </article>`;
  }

  function mountProducts() {
    const grid = document.getElementById('products-grid');
    if (!grid) return;
    grid.innerHTML = PRODUCTS.map(buildProductCard).join('');
  }

  /* ── Cart ──────────────────────────────────── */
  function getCartTotal() {
    let total = 0;
    for (const [id, qty] of CART) {
      const p = PRODUCTS.find(x => x.id === id);
      if (p) total += p.price * qty;
    }
    return total;
  }

  function getCartCount() {
    let count = 0;
    for (const qty of CART.values()) count += qty;
    return count;
  }

  function updateCartBadge() {
    const badge = document.getElementById('cart-count');
    const count = getCartCount();
    if (badge) {
      badge.textContent = count;
      badge.hidden = count === 0;
    }
  }

  function renderCartItems() {
    const container = document.getElementById('cart-items');
    if (!container) return;
    if (CART.size === 0) {
      container.innerHTML = `<p class="cart-empty">Your cart is empty.</p>`;
    } else {
      container.innerHTML = [...CART.entries()].map(([id, qty]) => {
        const p = PRODUCTS.find(x => x.id === id);
        if (!p) return '';
        return `
          <div class="cart-item" data-cart-item="${id}">
            <div class="cart-item-img" aria-hidden="true">${p.icon}</div>
            <div class="cart-item-info">
              <p class="cart-item-name">${p.name}</p>
              <p class="cart-item-price">$${p.price}</p>
              <div class="cart-item-qty">
                <button class="qty-btn" data-action="decrease" data-id="${id}" aria-label="Decrease quantity of ${p.name}">−</button>
                <span class="qty-num" aria-label="${qty} in cart">${qty}</span>
                <button class="qty-btn" data-action="increase" data-id="${id}" aria-label="Increase quantity of ${p.name}">+</button>
              </div>
            </div>
          </div>`;
      }).join('');
    }
    const subtotalEl = document.getElementById('cart-subtotal');
    if (subtotalEl) subtotalEl.textContent = `$${getCartTotal().toFixed(2)}`;
  }

  function addToCart(productId) {
    const id = Number(productId);
    CART.set(id, (CART.get(id) || 0) + 1);
    updateCartBadge();
    renderCartItems();
    const p = PRODUCTS.find(x => x.id === id);
    if (p) showToast(`${p.icon} "${p.name}" added to cart`);
  }

  function updateQty(id, delta) {
    const cur = CART.get(id) || 0;
    const next = cur + delta;
    if (next <= 0) CART.delete(id);
    else CART.set(id, next);
    updateCartBadge();
    renderCartItems();
  }

  /* ── Cart Drawer ───────────────────────────── */
  function openCart() {
    const drawer = document.getElementById('cart-drawer');
    const overlay = document.getElementById('cart-overlay');
    drawer?.classList.add('open');
    overlay?.classList.add('open');
    drawer?.setAttribute('aria-hidden', 'false');
    document.getElementById('close-cart')?.focus();
    document.body.style.overflow = 'hidden';
  }

  function closeCart() {
    const drawer = document.getElementById('cart-drawer');
    const overlay = document.getElementById('cart-overlay');
    drawer?.classList.remove('open');
    overlay?.classList.remove('open');
    drawer?.setAttribute('aria-hidden', 'true');
    document.getElementById('open-cart')?.focus();
    document.body.style.overflow = '';
  }

  /* ── Wishlist toggle ───────────────────────── */
  function toggleWishlist(btn) {
    const pressed = btn.getAttribute('aria-pressed') === 'true';
    btn.setAttribute('aria-pressed', String(!pressed));
    const productName = btn.closest('.product-card')?.querySelector('.product-name')?.textContent || 'Item';
    showToast(pressed ? `💔 Removed from wishlist` : `❤️ "${productName}" saved to wishlist`);
  }

  /* ── Toast ─────────────────────────────────── */
  function showToast(message) {
    const container = document.getElementById('toast-container');
    if (!container) return;
    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.setAttribute('role', 'status');
    toast.setAttribute('aria-live', 'polite');
    toast.textContent = message;
    container.appendChild(toast);
    requestAnimationFrame(() => {
      requestAnimationFrame(() => toast.classList.add('show'));
    });
    setTimeout(() => {
      toast.classList.remove('show');
      toast.addEventListener('transitionend', () => toast.remove(), { once: true });
    }, 3000);
  }

  /* ── Countdown Timer ───────────────────────── */
  function startCountdown() {
    const deadline = new Date();
    deadline.setHours(deadline.getHours() + 5, deadline.getMinutes() + 47, deadline.getSeconds() + 23);

    function update() {
      const now = new Date();
      let diff = Math.max(0, Math.floor((deadline - now) / 1000));
      const h = Math.floor(diff / 3600); diff %= 3600;
      const m = Math.floor(diff / 60);
      const s = diff % 60;

      const els = {
        hours: document.getElementById('cd-hours'),
        mins: document.getElementById('cd-mins'),
        secs: document.getElementById('cd-secs'),
      };
      if (els.hours) els.hours.textContent = String(h).padStart(2, '0');
      if (els.mins) els.mins.textContent = String(m).padStart(2, '0');
      if (els.secs) els.secs.textContent = String(s).padStart(2, '0');
    }
    update();
    setInterval(update, 1000);
  }

  /* ── Newsletter ─────────────────────────────── */
  function handleNewsletter(form) {
    form.addEventListener('submit', e => {
      e.preventDefault();
      const email = form.querySelector('input[type="email"]')?.value;
      if (email) {
        showToast(`✅ Thanks! You're subscribed with ${email}`);
        form.reset();
      }
    });
  }

  /* ── Category pills ─────────────────────────── */
  function initCategoryPills() {
    const pills = document.querySelectorAll('.category-pill');
    pills.forEach(pill => {
      pill.addEventListener('click', () => {
        pills.forEach(p => { p.setAttribute('aria-selected', 'false'); });
        pill.setAttribute('aria-selected', 'true');
      });
      pill.addEventListener('keydown', e => {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); pill.click(); }
      });
    });
  }

  /* ── Event delegation ───────────────────────── */
  function bindEvents() {
    document.addEventListener('click', e => {
      // Add to cart buttons
      const cartBtn = e.target.closest('.add-to-cart, .deal-add');
      if (cartBtn) {
        const card = cartBtn.closest('[data-product-id]');
        if (card) { addToCart(card.dataset.productId); return; }
        // Deal section fallback (hardcoded IDs for demo deal cards)
        const dealCard = cartBtn.closest('[data-deal-id]');
        if (dealCard) { addToCart(dealCard.dataset.dealId); return; }
        // Hero deal CTA
        if (cartBtn.classList.contains('deal-cta')) { addToCart(3); return; }
        // Generic
        addToCart(1);
        return;
      }
      // Wishlist
      const wishBtn = e.target.closest('.product-wishlist');
      if (wishBtn) { toggleWishlist(wishBtn); return; }
      // Cart drawer open/close
      if (e.target.closest('#open-cart')) { openCart(); return; }
      if (e.target.closest('#close-cart, #cart-overlay')) { closeCart(); return; }
      // Qty change
      const qtyBtn = e.target.closest('.qty-btn');
      if (qtyBtn) {
        const id = Number(qtyBtn.dataset.id);
        const action = qtyBtn.dataset.action;
        updateQty(id, action === 'increase' ? 1 : -1);
        return;
      }
    });

    // Keyboard: close drawer on Escape
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape') closeCart();
    });
  }

  /* ── Init ──────────────────────────────────── */
  function init() {
    mountProducts();
    bindEvents();
    startCountdown();
    initCategoryPills();
    updateCartBadge();

    const newsletterForm = document.getElementById('newsletter-form');
    if (newsletterForm) handleNewsletter(newsletterForm);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

