          </div>
        </div>
        <div class="product-footer">
          <div class="product-price">
            <span class="price-current">$${p.price}</span>
            ${p.original ? `<span class="price-original" aria-label="Original price $${p.original}">$${p.original}</span>` : ''}
            ${pct ? `<span class="price-discount" aria-label="${pct} percent off">${pct}% off</span>` : ''}
          </div>
          <button class="add-to-cart" aria-label="Add ${p.name} to cart">
            <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
              <path d="M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z"/><line x1="3" y1="6" x2="21" y2="6"/>
              <path d="M16 10a4 4 0 0 1-8 0"/>
            </svg>
            Add
          </button>
        </div>
      </article>`;
  }

  function mountProducts() {
